command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="559dc5266f16218af5613bfe9d7e7b426e7f37ad";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC completion diagnostic fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC completion diagnostic"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC completion diagnostic candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-completion-diag-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC diagnostic worktree add failed"}
 Set-Location -LiteralPath $temp
 & python -X utf8 tools\winui\check_python_static.py tests\winui\test_unc_transfer_gui.py
 if($LASTEXITCODE -ne 0){throw "UNC diagnostic harness static failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "UNC diagnostic Release build failed"}
 & python -X utf8 tools\winui\run_checks.py gui --area unc-copy-move --configuration Release
 if($LASTEXITCODE -eq 0){
   Write-Host "UNC_COMPLETION_DIAGNOSTIC_UNEXPECTED_PASS=TRUE"
 }else{
   Write-Host "UNC_COMPLETION_DIAGNOSTIC_EXPECTED_GUI_FAILURE=TRUE"
   exit 1
 }
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
